function createServiceApiKeyCell({
  hasApiKey = false,
  revealType = "",
  revealId = "",
  subject = "",
} = {}) {
  const cell = document.createElement("div");
  cell.className = "partner-data-list-row__api-key";
  if (!hasApiKey) {
    cell.textContent = "-";
    cell.setAttribute("aria-label", "No API key configured");
    return cell;
  }

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "sa-secret-field sa-secret-field--api-key";
  trigger.dataset.saApiKeyReveal = revealType;
  if (revealId) {
    trigger.dataset.apiKeyRevealId = revealId;
  }
  if (subject) {
    trigger.dataset.apiKeyRevealSubject = subject;
  }
  trigger.setAttribute("aria-label", `See API key for ${subject || "this service"}`);
  trigger.title = "See API key";

  const value = document.createElement("span");
  value.className = "sa-secret-field__value";
  value.textContent = "*******";
  value.setAttribute("aria-hidden", "true");

  const action = document.createElement("span");
  action.className = "sa-secret-field__action";

  const hoverLabel = document.createElement("span");
  hoverLabel.className = "sa-secret-field__hover-label";
  hoverLabel.textContent = "See API key";

  const icon = document.createElement("span");
  icon.className = "sa-secret-field__toggle-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = createIconSvg(integratedIconPaths.key);

  action.append(hoverLabel, icon);
  trigger.append(value, action);
  trigger.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    void revealServiceApiKey(trigger);
  });
  cell.append(trigger);
  return cell;
}

async function revealServiceApiKey(triggerButton) {
  if (!(triggerButton instanceof HTMLButtonElement)) {
    return;
  }

  const revealType = String(triggerButton.dataset.saApiKeyReveal || "").trim();
  const revealId = String(triggerButton.dataset.apiKeyRevealId || "").trim();
  const subject = String(triggerButton.dataset.apiKeyRevealSubject || "").trim();
  let revealUrl = "";

  if (revealType === "delivery-partner-api-key") {
    if (!revealId) {
      showSuperAdminSnackbar("API Key Reveal Failed", "Delivery partner could not be found.", "error");
      return;
    }
    revealUrl = `/api/delivery-partners/${encodeURIComponent(revealId)}/api-key`;
  } else if (revealType === "ai-integration-api-key") {
    if (!revealId) {
      showSuperAdminSnackbar("API Key Reveal Failed", "AI integration could not be found.", "error");
      return;
    }
    revealUrl = `/api/super-admin/ai-image-enhancement/${encodeURIComponent(revealId)}/api-key`;
  } else {
    showSuperAdminSnackbar("API Key Reveal Failed", "Unsupported API key reveal type.", "error");
    return;
  }

  triggerButton.disabled = true;
  try {
    if (!await requireSuperAdminFingerprint("view this API key")) {
      return;
    }
    const response = await fetch(revealUrl, {
      method: "GET",
      cache: "no-store",
      headers: rootHeaders({ Accept: "application/json" }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(data.message || "Unable to reveal the API key.");
    }
    const apiKey = String(data.apiKey ?? "").trim();
    if (!apiKey) {
      throw new Error("No API key is configured.");
    }
    showApiKeyRevealSnackbar({
      title: "API Key",
      subject,
      apiKey,
    });
  } catch (error) {
    showSuperAdminSnackbar(
      "API Key Reveal Failed",
      error instanceof Error ? error.message : "Unable to reveal the API key.",
      "error",
    );
  } finally {
    triggerButton.disabled = false;
  }
}
